void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
    fragColor = texelFetch(iChannel0,ivec2(mod(mod(fragCoord-iMouse.xy,iResolution.xy)+iResolution.xy,iResolution.xy)),0);
}

#define TWOPI 6.283185307179586
// speed of migration of the centers
#define SPEED 30.0
// number of regions
#define NUM_CELLS 50.0
// offset from the random texture
#define SEED 14.0
// thickness of the borders of each region (in pixels)
#define THICKNESS 4.0
// inclination of the indents at the edges
#define INCLINE 0.8

vec2 likeMod(vec2 dif,vec2 res) {
    return mod(mod(dif+res*0.5,res)+res,res)-res*0.5;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
    vec2 closest = 10.0*iResolution.xy;
    vec2 second = closest;
    for (float i = 0.0; i < NUM_CELLS; i++) {
        vec4 rng = texelFetch(iChannel0,ivec2(mod(i+SEED,iChannelResolution[0].x),mod((i+SEED)/iChannelResolution[0].x,iChannelResolution[0].y)),0);
        vec2 nuc = iResolution.xy*rng.xy;
        nuc += SPEED*iTime*vec2(cos(TWOPI*rng.z),sin(TWOPI*rng.z)); // movement
        nuc = likeMod(nuc-fragCoord,iResolution.xy)+fragCoord; //this line makes it tileable
        if (length(nuc-fragCoord) < length(closest-fragCoord)) {
            second = closest;
            closest = nuc;
        } else if (length(nuc-fragCoord) < length(second-fragCoord)) {
            second = nuc;
        }
    }
    float dist = (2.0*dot(fragCoord,closest-second) - dot(closest,closest) + dot(second,second))/length(closest-second)/2.0;
    if (dist < THICKNESS/2.0)
        fragColor = vec4(-0.5*INCLINE*normalize(closest-second)+vec2(.5),0.5*sqrt(1.0-INCLINE*INCLINE)+0.5,1);
    else fragColor = vec4(0.5,0.5,1,1);
}
